import crypto from 'node:crypto';
import {requireVendorMember} from '@/lib/vendors';
import {prisma} from '@/lib/prisma';
import {requestVendorPayout} from '@/app/vendor/actions';
export const dynamic='force-dynamic';
export default async function VendorPayouts({searchParams}:{searchParams:Promise<{vendorId?:string}>}){const p=await searchParams;const {vendor}=await requireVendorMember(p.vendorId);const [accounts,requests]=await Promise.all([prisma.vendorPayoutAccount.findMany({where:{vendorId:vendor.id,isActive:true}}),prisma.vendorPayoutRequest.findMany({where:{vendorId:vendor.id},orderBy:{requestedAt:'desc'},take:20})]);return <main className="admin-content"><p className="eyebrow">VENDOR FINANCE</p><h1 className="admin-title">Payouts</h1><p className="mt-2 text-sm text-slate-400">Payouts remain manual and are never marked paid before transfer confirmation.</p>{accounts.length?<form action={requestVendorPayout} className="admin-panel mt-8 max-w-xl space-y-4"><input type="hidden" name="vendorId" value={vendor.id}/><input type="hidden" name="idempotencyKey" value={crypto.randomUUID()}/><label>Account<select className="form-input" name="accountId">{accounts.map(a=><option key={a.id} value={a.id}>{a.method} · {a.accountName} ·••{a.accountNumber.slice(-4)}</option>)}</select></label><label>Amount MMK<input className="form-input" name="amountMmk" type="number" min="1" required/></label><button className="btn-primary">Request payout</button></form>:<div className="admin-panel mt-8">Add an approved payout account before requesting funds.</div>}<div className="admin-panel mt-8 overflow-x-auto"><table className="admin-table"><thead><tr><th>Amount</th><th>Status</th><th>Requested</th></tr></thead><tbody>{requests.map(r=><tr key={r.id}><td>{r.amountMmk.toLocaleString()} MMK</td><td>{r.status}</td><td>{r.requestedAt.toLocaleDateString()}</td></tr>)}</tbody></table></div></main>}
